- GET /uc/resources/workflowinstance/{id}
- GET /uc/resources/workflowinstance/{id}/dependencies
- GET /uc/resources/task/{id}
- GET /uc/resources/task
- GET /uc/resources/agent/{id}
- GET /uc/resources/agent
- POST /uc/resources/user/ops-login"

